import { join } from 'node:path'

/**
 * Tiny real videos generated by ffmpeg (`testsrc` + `sine`) for playback integration tests.
 * 160×90, 24 fps, a keyframe every 2 s (`-g 48`), B-frames on. The audio starts `audioDelayS` in.
 */

export type TestVideo = {
  container: 'mkv' | 'mp4'
  video: 'h264' | 'hevc'
  audio: 'aac' | 'ac3' | 'flac'
  durationS: number
  /** Default `yuv420p`; `yuv420p10le` for a 10-bit source (HEVC Main 10). */
  pixelFormat?: 'yuv420p' | 'yuv420p10le'
}

/**
 * The priming of the AAC (1024 samples) and AC-3 encoders puts the first audio packet before the
 * first frame (-21 ms with ffmpeg 6 and 7, not with 8): the container start would move with the
 * ffmpeg version, and every time relative to it. Started this late (and ending on time), the audio stays after 0.
 */
export const audioDelayS = 0.03

const encoders = { h264: 'libx264', hevc: 'libx265', aac: 'aac', ac3: 'ac3', flac: 'flac' }

export const hasFfmpeg = (): boolean =>
  (Bun.which('ffmpeg') ?? '') !== '' && (Bun.which('ffprobe') ?? '') !== ''

/** Builds without an encoder exist (Homebrew's ffmpeg 9 has no WebP one); the image's has them all. */
export const hasFfmpegEncoder = (name: string): boolean =>
  hasFfmpeg() &&
  Bun.spawnSync(['ffmpeg', '-hide_banner', '-h', `encoder=${name}`])
    .stdout.toString()
    .startsWith(`Encoder ${name} `)

export const generateVideo = async (dir: string, spec: TestVideo): Promise<string> => {
  const pixelFormat = spec.pixelFormat ?? 'yuv420p'
  const path = join(
    dir,
    `${spec.video}-${spec.audio}-${spec.durationS}s${pixelFormat === 'yuv420p' ? '' : `-${pixelFormat}`}.${spec.container}`,
  )
  const proc = Bun.spawn({
    cmd: [
      'ffmpeg',
      '-hide_banner',
      '-loglevel',
      'error',
      '-y',
      '-f',
      'lavfi',
      '-i',
      'testsrc=size=160x90:rate=24',
      '-itsoffset',
      String(audioDelayS),
      '-t',
      String(spec.durationS - audioDelayS),
      '-f',
      'lavfi',
      '-i',
      'sine=frequency=440:sample_rate=48000',
      '-t',
      String(spec.durationS),
      '-c:v',
      encoders[spec.video],
      '-preset',
      'ultrafast',
      '-g',
      '48',
      '-bf',
      '2',
      '-pix_fmt',
      pixelFormat,
      ...(spec.video === 'hevc'
        ? ['-x265-params', 'log-level=error:keyint=48:min-keyint=48:scenecut=0']
        : ['-sc_threshold', '0']),
      '-c:a',
      encoders[spec.audio],
      ...(spec.container === 'mp4' ? ['-movflags', '+faststart'] : []),
      path,
    ],
    stdout: 'ignore',
    stderr: 'pipe',
  })
  const [code, stderr] = await Promise.all([proc.exited, new Response(proc.stderr).text()])
  if (code !== 0) throw new Error(`ffmpeg failed to generate ${path}: ${stderr}`)
  return path
}

/** `ffprobe -show_streams -show_format` of a file, parsed. */
export const ffprobeJson = async (path: string) => {
  const proc = Bun.spawn({
    cmd: ['ffprobe', '-v', 'error', '-show_format', '-show_streams', '-of', 'json', path],
    stdout: 'pipe',
    stderr: 'pipe',
  })
  const [code, stdout, stderr] = await Promise.all([
    proc.exited,
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
  ])
  if (code !== 0) throw new Error(`ffprobe failed on ${path}: ${stderr}`)
  return JSON.parse(stdout) as {
    format: { duration?: string; format_name: string }
    streams: { codec_type: string; codec_name: string; duration?: string }[]
  }
}

/**
 * Decodes a whole file: proves a segment is playable, not just parseable. The null muxer's
 * "non monotonically increasing dts" notices are ignored: they come from ffmpeg rounding frame
 * times of negative-CTS fragments to the frame rate, not from the decoder.
 */
export const decodesCleanly = async (path: string): Promise<boolean> => {
  const proc = Bun.spawn({
    cmd: ['ffmpeg', '-v', 'error', '-xerror', '-i', path, '-f', 'null', '-'],
    stdout: 'ignore',
    stderr: 'pipe',
  })
  const [code, stderr] = await Promise.all([proc.exited, new Response(proc.stderr).text()])
  const problems = stderr
    .split('\n')
    .filter((line) => line.trim() !== '' && !line.includes('non monotonically increasing dts'))
  return code === 0 && problems.length === 0
}
